## Pattern (from Aleph `aleph/repl/sandbox.py:766-793`)

```python
before_ids = {k: id(v) for k, v in self._namespace.items()}
# ... execute ...
updated = [k for k, v in self._namespace.items() 
           if k not in before_ids or id(v) != before_ids[k]]
```

## PSFN Design

### Changes to `src/repl/sandbox.ts`

```typescript
// Before execute():
private snapshotKeys(): Map<string, unknown> {
  const snap = new Map<string, unknown>();
  for (const key of Object.getOwnPropertyNames(this.context)) {
    if (!this.builtinKeysSet.has(key)) {
      snap.set(key, this.context[key]);
    }
  }
  return snap;
}

// In execute():
async execute(code, timeoutMs, truncationLimit): Promise<ExecuteResult> {
  const before = this.snapshotKeys();
  // ... run code ...
  const after = this.snapshotKeys();
  const changed: string[] = [];
  for (const [k, v] of after) {
    if (!before.has(k) || before.get(k) !== v) changed.push(k);
  }
  return { output, error, finalAnswer, variablesChanged: changed };
}
```

